test("IElement deserialization fail", () => {
  const jsonable = "This is not a IElement.";

  const instanceOrError = AasJsonization.elementFromJsonable(
    jsonable
  );
  expect(instanceOrError.error.message).toStrictEqual(
    "Expected a JSON object, but got: string"
  );
});

